31	/**
32	 * Simple JavaBean domain object representing an owner.
33	 *
34	 * @author Ken Krebs
35	 * @author Juergen Hoeller
36	 * @author Sam Brannen
37	 * @author Michael Isvy
38	 */
39	@Entity
40	@Table(name = "owners")
41	public class Owner extends Person {
42	    @Column(name = "address")
43	    @NotEmpty
44	    private String address;
45	
46	    @Column(name = "city")
47	    @NotEmpty
48	    private String city;
49	
50	    @Column(name = "telephone")
51	    @NotEmpty
52	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Telephone must be in E.164 form (a '+' followed by 8 to 15 digits)")
53	    private String telephone;
54	
55	    @Column(name = "email")
56	    @Email
57	    private String email;
58	
59	    @Column(name = "registration_date")
60	    private LocalDate registrationDate;
61	
62	    @Column(name = "customer_code")
63	    private String customerCode;
64	
65	    @Column(name = "namesake_count")
66	    private Integer namesakeCount;
67	
68	    @Column(name = "bulk_signup_warning")
69	    private Boolean bulkSignupWarning;
70	
71	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
72	    private Set<Pet> pets;
73	
74	    public String getAddress() {
75	        return this.address;
76	    }
77	
78	    public void setAddress(String address) {
79	        this.address = normalizeAddress(address);
80	    }
81	
82	    public String getCity() {
83	        return this.city;
84	    }
85	
86	    public void setCity(String city) {
87	        this.city = city;
88	    }
89	
90	    public String getTelephone() {
91	        return this.telephone;
92	    }
93	
94	    public void setTelephone(String telephone) {
95	        this.telephone = telephone;
96	    }
97	
98	    public String getEmail() {
99	        return this.email;
100	    }
101	
102	    public void setEmail(String email) {
103	        this.email = normalizeEmail(email);
104	    }
105	
106	    public LocalDate getRegistrationDate() {
107	        return this.registrationDate;
108	    }
109	
110	    public void setRegistrationDate(LocalDate registrationDate) {
111	        this.registrationDate = registrationDate;
112	    }
113	
114	    public String getCustomerCode() {
115	        return this.customerCode;
116	    }
117	
118	    public void setCustomerCode(String customerCode) {
119	        this.customerCode = customerCode;
120	    }
121	
122	    public Integer getNamesakeCount() {
123	        return this.namesakeCount;
124	    }
125	
126	    public void setNamesakeCount(Integer namesakeCount) {
127	        this.namesakeCount = namesakeCount;
128	    }
129	
130	    public Boolean getBulkSignupWarning() {
131	        return this.bulkSignupWarning;
132	    }
133	
134	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
135	        this.bulkSignupWarning = bulkSignupWarning;
136	    }
137	
138	    /**
139	     * Normalize an email to its canonical stored form, which is lower-cased. This is the single
140	     * source of truth for how an email is persisted, so inputs that differ only in letter case
141	     * are stored identically. Applied by {@link #setEmail(String)} so every persistence path
142	     * (create and update, mapper or hand-copied) stores the same canonical value.
143	     *
144	     * @param email the raw email, possibly {@code null}
145	     * @return the lower-cased form, or {@code null} if the input was {@code null}
146	     */
147	    public static String normalizeEmail(String email) {
148	        return email == null ? null : email.toLowerCase();
149	    }
150	
151	    /**
152	     * Normalize a telephone to its canonical E.164 stored form. This is the single source of
153	     * truth for how a telephone is compared and persisted, so inputs that differ only in
154	     * formatting (spaces, dashes, brackets) are treated as the same number.
155	     *
156	     * <p>The rules are:
157	     * <ul>
158	     *   <li>spaces, dashes and brackets are stripped;</li>
159	     *   <li>a leading {@code '+'} and its country code are kept as given;</li>
160	     *   <li>otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
161	     *       is dropped from the national digits;</li>
162	     *   <li>the result must have 8 to 15 digits after the {@code '+'}.</li>
163	     * </ul>
164	     * For example {@code "0412 345 678"} becomes {@code "+61412345678"}. Already-normalized
165	     * values are returned unchanged.
166	     *
167	     * @param telephone the raw telephone, possibly {@code null}
168	     * @return the E.164 form, or {@code null} if the input is {@code null} or cannot form a
169	     *     valid E.164 number
170	     */
171	    public static String normalizeTelephone(String telephone) {
172	        if (telephone == null) {
173	            return null;
174	        }
175	        String trimmed = telephone.trim();
176	        boolean hasCountryCode = trimmed.startsWith("+");
177	        // Strip spaces, dashes and brackets; a leading '+' (if any) is left in place.
178	        String stripped = trimmed.replaceAll("[\\s\\-()]", "");
179	        if (hasCountryCode) {
180	            stripped = stripped.substring(1);
181	        }
182	        if (!stripped.matches("\\d+")) {
183	            return null;
184	        }
185	        String digits;
186	        if (hasCountryCode) {
187	            digits = stripped;
188	        } else {
189	            if (stripped.startsWith("0")) {
190	                stripped = stripped.substring(1);
191	            }
192	            digits = "61" + stripped;
193	        }
194	        if (digits.length() < 8 || digits.length() > 15) {
195	            return null;
196	        }
197	        return "+" + digits;
198	    }
199	
200	    /**
201	     * Common street-type abbreviations expanded by {@link #normalizeAddress(String)}, keyed by the
202	     * upper-cased abbreviation.
203	     */
204	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
205	        "ST", "STREET",
206	        "RD", "ROAD",
207	        "AVE", "AVENUE");
208	
209	    /**
210	     * Normalize an address to its canonical stored form. Leading and trailing whitespace is
211	     * trimmed, internal runs of whitespace are collapsed to a single space, the text is upper-cased,
212	     * and common street-type abbreviations are expanded as whole words ({@code ST}->{@code STREET},
213	     * {@code RD}->{@code ROAD}, {@code AVE}->{@code AVENUE}). This is the single source of truth for
214	     * how an address is persisted and compared, so inputs that differ only in letter case, spacing
215	     * or abbreviation are treated as the same address. Applied by {@link #setAddress(String)} so
216	     * every persistence path (create and update, mapper or hand-copied) stores the same canonical
217	     * value. The transform is idempotent: a normalized address normalizes to itself.
218	     *
219	     * @param address the raw address, possibly {@code null}
220	     * @return the normalized form, or {@code null} if the input was {@code null}
221	     */
222	    public static String normalizeAddress(String address) {
223	        if (address == null) {
224	            return null;
225	        }
226	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase();
227	        if (collapsed.isEmpty()) {
228	            return collapsed;
229	        }
230	        String[] tokens = collapsed.split(" ");
231	        StringBuilder normalized = new StringBuilder(collapsed.length());
232	        for (int i = 0; i < tokens.length; i++) {
233	            if (i > 0) {
234	                normalized.append(' ');
235	            }
236	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
237	        }
238	        return normalized.toString();
239	    }
240	
241	    /**
242	     * Normalize a household field (such as last name or address) to its canonical form for
243	     * duplicate-household comparison. Leading and trailing whitespace is trimmed, internal runs
244	     * of whitespace are collapsed to a single space, and the result is lower-cased, so inputs
245	     * that differ only in letter case or spacing are treated as the same value.
246	     *
247	     * @param value the raw field value, possibly {@code null}
248	     * @return the normalized form, or {@code null} if the input was {@code null}
249	     */
250	    public static String normalizeHousehold(String value) {
251	        if (value == null) {
252	            return null;
253	        }
254	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
255	    }
256	
257	    /**
258	     * Compute the stable identifier shared by all owners in the same household, i.e. with the same
259	     * last name (compared case-insensitively with collapsed whitespace, see
260	     * {@link #normalizeHousehold(String)}) and the same normalized address (see
261	     * {@link #normalizeAddress(String)}). The value is deterministic in those two fields, so two
262	     * owners who share a household are assigned the same id. It is formatted {@code 'HH-<HEX12>'}
263	     * where {@code HEX12} is the first twelve upper-cased hex characters of the SHA-256 digest of
264	     * the normalized last name and address.
265	     *
266	     * @param lastName the owner's last name, possibly {@code null}
267	     * @param address the owner's address, possibly {@code null}
268	     * @return the household id, or {@code null} if either field is {@code null}
269	     */
270	    public static String householdId(String lastName, String address) {
271	        String normalizedLastName = normalizeHousehold(lastName);
272	        String normalizedAddress = normalizeAddress(address);
273	        if (normalizedLastName == null || normalizedAddress == null) {
274	            return null;
275	        }
276	        String key = normalizedLastName + "\n" + normalizedAddress;
277	        try {
278	            byte[] digest = MessageDigest.getInstance("SHA-256")
279	                .digest(key.getBytes(StandardCharsets.UTF_8));
280	            StringBuilder hex = new StringBuilder(digest.length * 2);
281	            for (byte b : digest) {
282	                hex.append(String.format("%02x", b));
283	            }
284	            return "HH-" + hex.substring(0, 12).toUpperCase();
285	        } catch (NoSuchAlgorithmException e) {
286	            // SHA-256 is a standard algorithm required to be present on every JVM.
287	            throw new IllegalStateException("SHA-256 not available", e);
288	        }
289	    }
290	
291	    /**
292	     * Build an owner's {@code membershipNumber}, the stable membership identifier derived from the
293	     * owner's own persisted fields. It is formatted {@code '<customerCode>-M<YY>'} where {@code YY}
294	     * is the last two digits of the registration date's year (e.g. {@code 'LON-SMI-0007-M26'}). The
295	     * value is deterministic in those two fields.
296	     *
297	     * @param customerCode the owner's customer code, possibly {@code null}
298	     * @param registrationDate the owner's registration date, possibly {@code null}
299	     * @return the membership number, or {@code null} if either field is {@code null}
300	     */
301	    public static String membershipNumber(String customerCode, LocalDate registrationDate) {
302	        if (customerCode == null || registrationDate == null) {
303	            return null;
304	        }
305	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
306	    }
307	
308	    /**
309	     * Build an owner's {@code membershipLevel}, the derived numeric level assigned on create. The
310	     * value starts at 1, gains 1 when an email is present and gains 1 when {@code namesakeCount} is 0,
311	     * and is capped at 3 (level 4 is reserved for tenure). The value is deterministic in those two
312	     * fields.
313	     *
314	     * @param namesakeCount the owner's namesake count, possibly {@code null}
315	     * @param email the owner's email, possibly {@code null}
316	     * @return the membership level, an integer from 1 to 3
317	     */
318	    public static int membershipLevel(Integer namesakeCount, String email) {
319	        int level = 1;
320	        if (email != null && !email.isEmpty()) {
321	            level++;
322	        }
323	        if (namesakeCount != null && namesakeCount == 0) {
324	            level++;
325	        }
326	        return Math.min(level, 3);
327	    }
328	
329	    /**
330	     * Fixed city-to-region table used by {@link #locality(String)} to derive an owner's locality,
331	     * keyed by the exact city name.
332	     */
333	    private static final Map<String, String> CITY_REGION = Map.of(
334	        "Sydney", "NSW",
335	        "Melbourne", "VIC",
336	        "Brisbane", "QLD");
337	
338	    /**
339	     * Derive an owner's {@code locality}, the canonical region for the owner's city, from the fixed
340	     * city-to-region table ({@code Sydney}->{@code NSW}, {@code Melbourne}->{@code VIC},
341	     * {@code Brisbane}->{@code QLD}). The value is deterministic in the city. A city not in the
342	     * table (including {@code null}) derives {@code 'UNKNOWN'}.
343	     *
344	     * @param city the owner's city, possibly {@code null}
345	     * @return the canonical region string, or {@code 'UNKNOWN'} when the city is not in the table
346	     */
347	    public static String locality(String city) {
348	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
349	    }
350	
351	    protected Set<Pet> getPetsInternal() {
352	        if (this.pets == null) {
353	            this.pets = new HashSet<>();
354	        }
355	        return this.pets;
356	    }
357	
358	    protected void setPetsInternal(Set<Pet> pets) {
359	        this.pets = pets;
360	    }
361	
362	    public List<Pet> getPets() {
363	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
364	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
365	        return Collections.unmodifiableList(sortedPets);
366	    }
367	
368	    public void setPets(List<Pet> pets) {
369	        this.pets = new HashSet<>(pets);
370	    }
371	
372	    public void addPet(Pet pet) {
373	        getPetsInternal().add(pet);
374	        pet.setOwner(this);
375	    }
376	
377	    /**
378	     * Return the Pet with the given name, or null if none found for this Owner.
379	     *
380	     * @param name to test
381	     * @return true if pet name is already in use
382	     */
383	    public Pet getPet(String name) {
384	        return getPet(name, false);
385	    }
386	
387	    /**
388	     * Return the Pet with the given name, or null if none found for this Owner.
389	     *
390	     * @param name to test
391	     * @return true if pet name is already in use
392	     */
393	    public Pet getPet(String name, boolean ignoreNew) {
394	        name = name.toLowerCase();
395	        for (Pet pet : getPetsInternal()) {
396	            if (!ignoreNew || !pet.isNew()) {
397	                String compName = pet.getName();
398	                compName = compName.toLowerCase();
399	                if (compName.equals(name)) {
400	                    return pet;
401	                }
402	            }
403	        }
404	        return null;
405	    }
406	
407	    public Pet getPet(Integer petId) {
408	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
409	    }
410	
411	    @Override
412	    public String toString() {
413	        return new ToStringCreator(this)
414	
415	            .append("id", this.getId())
416	            .append("new", this.isNew())
417	            .append("lastName", this.getLastName())
418	            .append("firstName", this.getFirstName())
419	            .append("address", this.address)
420	            .append("city", this.city)
421	            .append("telephone", this.telephone)
422	            .toString();
423	    }
424	}
